+        assertThat(clusterInfo.get(REMOTE_CLUSTER_1).isConnected(), equalTo(false));
+        assertThat(
+            clusterInfo.get(REMOTE_CLUSTER_1).getError(),
+            equalTo("Request timed out before receiving a response from the remote cluster")
+        );
+    }
+}

