+
+        var resp = (FullHttpResponse) channel.readOutbound();
+        assertEquals("should respond with 413", HttpResponseStatus.REQUEST_ENTITY_TOO_LARGE, resp.status());
+        assertFalse("should close channel", channel.isOpen());
+        resp.release();
+    }
+
+}

