-            clusterService.state(),
-            indexNameExpressionResolver,
-            transportService.getRemoteClusterService(),
-            System.currentTimeMillis()
-        );
-
-        return searchService.getRewriteContext(() -> System.currentTimeMillis(), resolvedIndices, null);
-    }
