-                results.put(entry.getKey(), rewritten);
-            }
-
-            return hasChanged ? new FullTextFunctionsRewritable(results) : this;
-        }
-
-        public Map<FullTextFunction, QueryBuilder> results() {
-            return queryBuilderMap;
-        }
-    }
